// Q.E.D. High-Assurance Implementation
interface PaymentResponse {
  status: string;
  amountMinor: number;
}

export async function getPaymentStatus(txId: string, timeoutMs = 5000): Promise<PaymentResponse> {
  const res = await fetch(`https://api.payments.net/tx/${encodeURIComponent(txId)}`, {
    signal: AbortSignal.timeout(timeoutMs),
    headers: { 'Accept': 'application/json' }
  });
  if (!res.ok) {
    throw new Error(`Payment gateway error: ${res.status}`);
  }
  return (await res.json()) as PaymentResponse;
}

