// Q.E.D. High-Assurance Implementation
export interface Account {
  id: string;
  isActive: boolean;
}

function isAccount(obj: unknown): obj is Account {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    typeof (obj as Record<string, unknown>).id === 'string' &&
    typeof (obj as Record<string, unknown>).isActive === 'boolean'
  );
}

export function parseAccount(rawJson: string): Account {
  const parsed: unknown = JSON.parse(rawJson);
  if (!isAccount(parsed)) {
    throw new TypeError('Invalid Account schema format');
  }
  return parsed;
}

